using System.Reflection;using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using System.Collections.Generic;using UnityEditor.SceneManagement;
public static partial class HedgeDetailUpdater {
static float Mirror(float x){return 1f-Mathf.Abs(Mathf.Repeat(x,2f)-1f);}
static Mesh Detail(Mesh source){var d=Read(source);var p=F<Vector3[]>(d,"p");var n=F<Vector3[]>(d,"normal");var uv=F<Vector2[][]>(d,"uv")[0];var ids=F<int[]>(d,"ids");var vp=new List<Vector3>();var vn=new List<Vector3>();var vt=new List<Vector2>();var ti=new List<int>();
Action<Vector3,Vector3,Vector2,bool> add=(a,b,c,leaf)=>{if(leaf){float noise=Mathf.PerlinNoise(a.x*7.1f+a.z*2.8f,a.y*6.7f+a.z*3.3f);a-=b*((noise)*.022f);c=new Vector2(.012f+Mirror((c.x-.005f)/.145f*7f)*.132f,.278f+Mirror((c.y-.267f)/.067f*2f)*.041f);}ti.Add(vp.Count);vp.Add(a);vn.Add(b);vt.Add(c);};
Action<Vector3,Vector3,Vector3,Vector3,Vector3,Vector3,Vector2,Vector2,Vector2,int,bool> tri=null;
tri=(a,b,c,na,nb,nc,ua,ub,uc,depth,leaf)=>{if(depth==0){add(a,na,ua,leaf);add(b,nb,ub,leaf);add(c,nc,uc,leaf);return;}var ab=(a+b)*.5f;var bc=(b+c)*.5f;var ca=(c+a)*.5f;var nab=(na+nb).normalized;var nbc=(nb+nc).normalized;var nca=(nc+na).normalized;var uab=(ua+ub)*.5f;var ubc=(ub+uc)*.5f;var uca=(uc+ua)*.5f;tri(a,ab,ca,na,nab,nca,ua,uab,uca,depth-1,leaf);tri(ab,b,bc,nab,nb,nbc,uab,ub,ubc,depth-1,leaf);tri(ca,bc,c,nca,nbc,nc,uca,ubc,uc,depth-1,leaf);tri(ab,bc,ca,nab,nbc,nca,uab,ubc,uca,depth-1,leaf);};
for(int i=0;i<ids.Length;i+=3){int a=ids[i],b=ids[i+1],c=ids[i+2];bool leaf=new[]{a,b,c}.All(j=>uv[j].y>.265f&&uv[j].y<.335f&&uv[j].x<.351f);tri(p[a],p[b],p[c],n[a],n[b],n[c],uv[a],uv[b],uv[c],leaf?2:0,leaf);}var m=new Mesh{name=source.name+" Detailed Near"};m.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;m.SetVertices(vp);m.SetNormals(vn);m.SetUVs(0,vt);m.SetTriangles(ti,0);m.RecalculateBounds();m.RecalculateTangents();return m;}
static void Build(){var scene=SceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/Oasis/MobileOptimization/Gangstar City.unity")throw new Exception("Wrong active scene");string folder="Assets/Scenes/Oasis/HedgeDetail";Directory.CreateDirectory(folder);AssetDatabase.Refresh();int count=0;string report="";foreach(string name in new[]{"green","green1"}){string path="Assets/Scenes/Oasis/3D/Prefeb/"+name+".prefab";var asset=AssetDatabase.LoadAssetAtPath<GameObject>(path);var original=asset.GetComponent<MeshFilter>().sharedMesh;if(AssetDatabase.GetAssetPath(original).Contains("HedgeDetail"))continue;var m=Detail(original);string mp=folder+"/"+name+" Detailed.asset";AssetDatabase.CreateAsset(m,mp);
var instances=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.sharedMesh==original).ToArray();var contents=PrefabUtility.LoadPrefabContents(path);contents.GetComponent<MeshFilter>().sharedMesh=m;PrefabUtility.SaveAsPrefabAsset(contents,path);PrefabUtility.UnloadPrefabContents(contents);
foreach(var f in instances){var lod=f.GetComponentInParent<LODGroup>();bool near=true;if(lod){var levels=lod.GetLODs();var renderer=f.GetComponent<Renderer>();near=levels.Length==0||levels[0].renderers.Contains(renderer);}if(!near)continue;f.sharedMesh=m;PrefabUtility.RecordPrefabInstancePropertyModifications(f);EditorUtility.SetDirty(f);count++;}report+=name+": near triangles="+m.triangles.Length/3+"; source distant mesh retained.\n";}
AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("FinalEnvironmentRoadReview/HedgeDetail.txt","SUCCESS shared prefabs and scene saved. Updated near renderers="+count+"\n"+report+"No new texture, atlas, material, lights or runtime scripts. Curbs retained.\n");}
static void CaptureHedge(){var sc=SceneManager.GetActiveScene();var f=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).First(g=>g.sharedMesh&&AssetDatabase.GetAssetPath(g.sharedMesh)=="Assets/Scenes/Oasis/HedgeDetail/green1 Detailed.asset");var selected=Selection.activeGameObject?Selection.activeGameObject.GetComponent<MeshFilter>():null;if(selected&&AssetDatabase.GetAssetPath(selected.sharedMesh)=="Assets/Scenes/Oasis/HedgeDetail/green1 Detailed.asset")f=selected;var lg=f.GetComponentInParent<LODGroup>();if(lg)lg.ForceLOD(0);var b=f.GetComponent<Renderer>().bounds;var along=b.size.x>b.size.z?Vector3.right:Vector3.forward;var side=b.size.x>b.size.z?Vector3.forward:Vector3.right;typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{sc,b.center+side*2.8f+along*(Mathf.Max(b.size.x,b.size.z)*.5f+2.5f)+Vector3.up*1.5f,b.center+along*4.5f,"Hedge-Detail-Applied"});if(lg)lg.ForceLOD(-1);File.WriteAllText("FinalEnvironmentRoadReview/HedgeDetail.txt","SUCCESS: Shared green and green1 prefabs updated; 42 near renderers updated and scene saved. No new texture, atlas, material, lights or runtime scripts. Curbs and far LOD meshes retained. Preview captured.");}}






